EXACT SERIALIZATION PSEUDOCODE (verified with 0 mismatches over 3,839 inputs):

std::string to_string() const {
    std::string r;
    if (!scheme_.empty()) {          // identical to has_scheme()
        r += scheme_;               // already ASCII-lowercased at parse time
        r += "://";
        r += authority();           // reconstructed, see next rule
    }
    r += path_;                     // verbatim, unconditional, no leading '/' ever synthesized
    if (!query_.empty())    { r += '?'; r += query_; }
    if (!fragment_.empty()) { r += '#'; r += fragment_; }
    return r;
}

No other field or has_* flag participates. There is no percent-encoding, no escaping, no normalization, no trimming: all bytes (including TAB, CR, LF, UTF-8, spaces) are copied through verbatim.
